//mainwindow.xaml.cs
public partial class mainwindow : window
{
    wpfcontext db = wpfcontext.getinstance();
    private user currentuser;
    private list<equipment> equipments;
    private list<equipment> allequipments;
    private list<equipment> filteredequipments;

public mainwindow(user user)
{
    initializecomponent();
    currentuser = user;
    setupui();
    allequipments = db.equipment
                    .include(e = > e.idmanufacturernavigation)
                    .include(e = > e.idrenttimenavigation)
                    .include(e = > e.idsuppliernavigation)
                    .include(e = > e.idtypenavigation)
                    .tolist();

    sortbymanufacturer.items.clear();
    sortbymanufacturer.items.add("все производители");
    foreach (var m in allequipments.select(e = > e.idmanufacturernavigation.manufacturer1).distinct())
        sortbymanufacturer.items.add(m);

    sortbymanufacturer.selectedindex = 0;

    applyfilterandsort();

    searchbox.textchanged += (s, e) = > applyfilterandsort();
    sortbymanufacturer.selectionchanged += (s, e) = > applyfilterandsort();
    downtoupradiobutton.checked += (s, e) = > applyfilterandsort();
    uptodownradiobutton.checked += (s, e) = > applyfilterandsort();
}

private void setupui()
{
    if (currentuser != null)
    {
        fullnametext.text = currentuser.fullname;
        roletext.text = currentuser.idrolenavigation.role1;

        switch (currentuser.idrolenavigation.role1)
        {
            case "администратор":
                addbutton.visibility = visibility.visible;
                deletebutton.visibility = visibility.visible;
                editbutton.visibility = visibility.visible;

                searchbox.visibility = visibility.visible;
                sortbymanufacturer.visibility = visibility.visible;
                downtoupradiobutton.visibility = visibility.visible;
                uptodownradiobutton.visibility = visibility.visible;
                break;
            case "менеджер":
                searchbox.visibility = visibility.visible;
                sortbymanufacturer.visibility = visibility.visible;
                downtoupradiobutton.visibility = visibility.visible;
                uptodownradiobutton.visibility = visibility.visible;
                break;
        }
    }
    else
    {
        fullnametext.text = "гость";
        roletext.text = "гость";
    }
}

private void loadequipments()
{
    equipments = db.equipment
        .include(e = > e.idmanufacturernavigation)
        .include(e = > e.idrenttimenavigation)
        .include(e = > e.idsuppliernavigation)
        .include(e = > e.idtypenavigation)
        .tolist();

    equipmentlist.itemssource = equipments;
}

private void exitbutton_click(object sender, routedeventargs e)
{
    authorizationwindow authorizationwindow = new authorizationwindow();
    authorizationwindow.show();
    this.close();
}

private void applyfilterandsort()
{
    if (allequipments == null) return;

    string search = searchbox.text?.tolower() ?? "";
    var filtered = allequipments
        .where(e = > e.name.tolower().contains(search))
        .tolist();

    // фильтр по производителю
    if (sortbymanufacturer.selecteditem is string manufacturer && manufacturer != "все производители")
    {
        filtered = filtered
            .where(e = > e.idmanufacturernavigation.manufacturer1 == manufacturer)
            .tolist();
    }

    // сортировка цены
    if (downtoupradiobutton.ischecked == true)
        filtered = filtered.orderby(e = > e.price).tolist();
    else if (uptodownradiobutton.ischecked == true)
        filtered = filtered.orderbydescending(e = > e.price).tolist();

    equipmentlist.itemssource = filtered;
}
}
